import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E7%BE%A4%E7%A1%95%E8%BD%AF%E4%BB%B6/","title":"群硕软件 | notes","lang":"zh-CN","frontmatter":{"title":"群硕软件","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/真实面经/群硕软件/","description":"面向对象是什么？举个生活中的例子 多喝热水 面对过程：把水倒入热水�?》接�?》开始烧�?》完成烧�?》倒入水杯 面向对象：水，热水壶，杯子，�? 面对过程和面向对象的区别�? 面向过程 �?面向过程性能比面向对象高�? 因为类调用时需要实例化，开销比较大，比较消耗资源，所以当性能是最重要的考量因素的时候，比如单片机、嵌入式开发、Linux/Unix ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"群硕软件\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-09-29T08:54:52.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E7%BE%A4%E7%A1%95%E8%BD%AF%E4%BB%B6/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"群硕软件"}],["meta",{"property":"og:description","content":"面向对象是什么？举个生活中的例子 多喝热水 面对过程：把水倒入热水�?》接�?》开始烧�?》完成烧�?》倒入水杯 面向对象：水，热水壶，杯子，�? 面对过程和面向对象的区别�? 面向过程 �?面向过程性能比面向对象高�? 因为类调用时需要实例化，开销比较大，比较消耗资源，所以当性能是最重要的考量因素的时候，比如单片机、嵌入式开发、Linux/Unix ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-29T08:54:52.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-29T08:54:52.000Z"}]]},"readingTime":{"minutes":11.46,"words":3438},"git":{"createdTime":1775331561000,"updatedTime":1790672092000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":3,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":2,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"0604e3c3eb461ee2caed5c6e4abd491a9923782f","time":1790672092000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新"},{"hash":"2b8fbfd20adad3bfab38722d9a766aa8cda1d261","time":1783768393000,"email":"tu_aofei@163.com","author":"xiaofei","message":"替换无用图片"},{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"6d0979cab855c606d3bb78839721f080e7d9ac6a","time":1777472166000,"email":"tu_aofei@163.com","author":"xiaofei","message":"打包更新不符合规范的语法"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/真实面经/群硕软件.md","headers":[],"bulletin":true}`),a={name:`群硕软件.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="面向对象是什么-举个生活中的例子" tabindex="-1"><a class="header-anchor" href="#面向对象是什么-举个生活中的例子"><span>面向对象是什么？举个生活中的例子</span></a></h2><p>多喝热水</p><p>面对过程：把水倒入热水�?》接�?》开始烧�?》完成烧�?》倒入水杯</p><p>面向对象：水，热水壶，杯子，�?</p><h2 id="面对过程和面向对象的区别�" tabindex="-1"><a class="header-anchor" href="#面对过程和面向对象的区别�"><span>面对过程和面向对象的区别�?</span></a></h2><p><strong>面向过程</strong> �?<em>面向过程性能比面向对象高�?</em> 因为类调用时需要实例化，开销比较大，比较消耗资源，所以当性能是最重要的考量因素的时候，比如单片机、嵌入式开发、Linux/Unix 等一般采用面向过程开发。但是，**面向过程没有面向对象易维护、易复用、易扩展�?*</p><p><strong>面向对象</strong> �?<em>面向对象易维护、易复用、易扩展�?</em> 因为面向对象有封装、继承、多态性的特性，所以可以设计出低耦合的系统，使系统更加灵活、更加易于维护。但是，<strong>面向对象性能比面向过程低</strong>�?</p><h2 id="面向对象的特征以及他们的作用" tabindex="-1"><a class="header-anchor" href="#面向对象的特征以及他们的作用"><span>面向对象的特征以及他们的作用</span></a></h2><h4 id="封装" tabindex="-1"><a class="header-anchor" href="#封装"><span>封装</span></a></h4><p>封装是指把一个对象的状态信息（也就是属性）隐藏在对象内部，不允许外部对象直接访问对象的内部信息。但是可以提供一些可以被外界访问的方法来操作属性�?</p><h4 id="继承" tabindex="-1"><a class="header-anchor" href="#继承"><span>继承</span></a></h4><p>不同类型的对象，相互之间经常有一定数量的共同点�? 继承是使用已存在的类的定义作为基础建立新类的技术，新类的定义可以增加新的数据或新的功能，也可以用父类的功能，但不能选择性地继承父类�?</p><p>子类拥有父类对象所有的属性和方法（包括私有属性和私有方法），但是父类中的私有属性和方法子类是无法访问，<strong>只是拥有</strong>�? 子类可以拥有自己属性和方法，即子类可以对父类进行扩展�? 子类可以用自己的方式实现父类的方法�?</p><h4 id="多�" tabindex="-1"><a class="header-anchor" href="#多�"><span>多�?</span></a></h4><p>表示一个对象具有多种的状态。具体表现为父类的引用指向子类的实例</p><p><strong>多态的特点:</strong></p><ul><li>对象类型和引用类型之间具有继承（类）/实现（接口）的关系；</li><li>引用类型变量发出的方法调用的到底是哪个类中的方法，必须在程序运行期间才能确定�?- 多态不能调用“只在子类存在但在父类不存在”的方法�?- 如果子类重写了父类的方法，真正执行的是子类覆盖的方法，如果子类没有覆盖父类的方法，执行的是父类的方法�?</li></ul><h2 id="简述tcp的三次握�" tabindex="-1"><a class="header-anchor" href="#简述tcp的三次握�"><span>简述TCP的三次握�?</span></a></h2><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282033529.png" alt="image-20211127161115751" style="zoom:67%;"><p><strong>三次握手最主要的目的就是双方确认自己与对方的发送与接收是正常的</strong></p><h3 id="�-2-次握手传回了-ack-为什么还要传�-syn�" tabindex="-1"><a class="header-anchor" href="#�-2-次握手传回了-ack-为什么还要传�-syn�"><span>�?2 次握手传回了 ACK，为什么还要传�?SYN�?</span></a></h3><p>接收端传回发送端所发送的 ACK 是为了告诉客户端，我接收到的信息确实就是你所发送的信号了，这表明从客户端到服务端的通信是正常的。而回�?SYN 则是为了建立并确认从服务端到客户端的通信�?</p><h2 id="四次挥手" tabindex="-1"><a class="header-anchor" href="#四次挥手"><span>四次挥手</span></a></h2><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282033499.png" alt="image-20211127162028159" style="zoom:67%;"><ul><li>客户�?发送一�?FIN，用来关闭客户端到服务器的数据传�?- 服务�?收到这个 FIN，它发回一 �?ACK，确认序号为收到的序号加 1 。和 SYN 一样，一�?FIN 将占用一个序�?- 服务�?关闭与客户端的连接，发送一�?FIN 给客户端</li><li>客户�?发回 ACK 报文确认，并将确认序号设置为收到序号�?1</li></ul><p>任何一方都可以在数据传送结束后发出连接释放的通知，待对方确认后进入半关闭状态。当另一方也没有数据再发送的时候，则发出连接释放通知，对方确认后就完全关闭了 TCP 连接�?</p><p>A �?B 打电话，通话即将结束后，A 说“我没啥要说的了”，B 回答“我知道了”，但是 B 可能还会有要说的话，A 不能要求 B 跟着自己的节奏结束通话，于�?B 可能又巴拉巴拉说了一通，最�?B 说“我说完了”，A 回答“知道了”，这样通话才算结束�?</p><h2 id="session和cookie的区�" tabindex="-1"><a class="header-anchor" href="#session和cookie的区�"><span>Session和cookie的区�?</span></a></h2><p>*<em>Cookie 一般用来保存用户信�?</em></p><p>�?我们�?Cookie 中保存已经登录过得用户信息，下次访问网站的时候页面可以自动帮你登录的一些基本信息给填了�? �?一般的网站都会有保持登录也就是说下次你再访问网站的时候就不需要重新登录了，这是因为用户登录的时候我们可以存放了一�?Token �?Cookie 中，下次登录的时候只需要根�?Token 值来查找用户即可(为了安全考虑，重新登录一般要�?Token 重写)�? �?登录一次网站后访问网站其他页面不需要重新登录�? <em><em>Session 的主要作用就是通过服务端记录用户的状态�?</em> 典型的场景是购物车，当你要添加商品到购物车的时候，系统不知道是哪个用户操作的，因为 HTTP 协议是无状态的。服务端给特定的用户创建特定�?Session 之后就可以标识这个用户并且跟踪这个用户了�? Cookie 数据保存�?*客户�?浏览器端)</em><em>，Session 数据保存�?*服务器端</em>*�? Cookie 存储在客户端中，�?Session 存储在服务器上，相对来说 Session 安全性更高。如果要�?Cookie 中存储一些敏感信息，不要直接写入 Cookie 中，最好能�?Cookie 信息加密然后使用到的时候再去服务器端解�?</p><h2 id="为什么要创建单例" tabindex="-1"><a class="header-anchor" href="#为什么要创建单例"><span>为什么要创建单例</span></a></h2><p>对于频繁使用的对象，可以省略创建对象所花费的时间，这对于那些重量级对象而言，是非常可观的一笔系统开销�? 由于 new 操作的次数减少，因而对系统内存的使用频率也会降低，这将减轻 GC 压力，缩�?GC 停顿时间�?</p><h2 id="简述java垃圾回收机制" tabindex="-1"><a class="header-anchor" href="#简述java垃圾回收机制"><span>简述java垃圾回收机制</span></a></h2><p>Java 的自动内存管理主要是针对对象内存的回收和对象内存的分配。同时，Java 自动内存管理最核心的功能是 <em><em>�?</em> 内存中对象的分配与回收�? Java 堆是垃圾收集器管理的主要区域，因此也被称�?<em>GC 堆（Garbage Collected Heap�?</em>.从垃圾回收的角度，由于现在收集器基本都采�?*分代垃圾收集算法</em>*，所�?Java 堆还可以细分为：新生代和老年�? <img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282033896.png" alt="image-20211127162808126" style="zoom:67%;"></p><ol><li><p>创建和分配内�?</p></li><li><p>判断对象是否死亡 引用计数[<strong><s>对象之间相互循环引用</s></strong>]、可达性分析<img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282032989.png" alt="image-20211127163737353" style="zoom:50%;">四种引用[强、弱、软、虚]</p><ol><li><p>当内存空间不足，Java 虚拟机宁愿抛�?OutOfMemoryError 错误，使程序异常终止，也不会靠随意回收具有强引用的对象来解决内存不足问题</p></li><li><p>如果内存空间足够，垃圾回收器就不会回收它，如果内存空间不足了，就会回收这些对象的内存�?</p></li><li><p>弱引用与软引用的区别在于：只具有弱引用的对象拥有更短暂的生命周期。在垃圾回收器线程扫描它所管辖的内存区域的过程中，一旦发现了只具有弱引用的对象，不管当前内存空间足够与否，都会回收它的内存�?</p></li><li><p>虚引用并不会决定对象的生命周期。如果一个对象仅持有虚引用，那么它就和没有任何引用一样，在任何时候都可能被垃圾回收�?<em>虚引用主要用来跟踪对象被垃圾回收的活�?</em>�?</p><blockquote><p><strong>虚引用与软引用和弱引用的一个区别在于：</strong> 虚引用必须和引用队列（ReferenceQueue）联合使用。当垃圾回收器准备回收一个对象时，如果发现它还有虚引用，就会在回收对象的内存之前，把这个虚引用加入到与之关联的引用队列中。程序可以通过判断引用队列中是否已经加入了虚引用，来了解被引用的对象是否将要被垃圾回收。程序如果发现某个虚引用已经被加入到引用队列，那么就可以在所引用的对象的内存被回收之前采取必要的行动�?</p></blockquote></li></ol></li><li><p>回收算法</p></li></ol><h2 id="jvm是什么-工作原理" tabindex="-1"><a class="header-anchor" href="#jvm是什么-工作原理"><span>jvm是什么？工作原理</span></a></h2><p>JVM 又被称作 Java 虚拟机，用来运行 Java 字节码文件（<code>.class</code>�? Java文件经过编译后变�?.class 字节码文�? 字节码文件通过类加载器被搬运到 JVM 虚拟机中</p><p>虚拟机主要的5大块：<u><strong>方法区</strong></u>、<u><strong>堆</strong></u>都为线程共享区域，有线程安全问题；<u><strong>栈</strong></u>、<u><strong>本地方法栈</strong></u>、<u><strong>计数器</strong></u>都是独享区域，不存在线程安全问题，故 JVM 的调优主要就是围绕堆、栈两大块进行 <img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282033228.png" alt="image-20211127164747814" style="zoom:67%;"></p><p><strong>加载</strong></p><ol><li><p>通过一个类的全限定名来获取定义此类的二进制字节流�?2. 将这个二进制字节流所代表的静态存储结构导入为方法区的运行时数据结构�?3. 在java堆中生成一个java.lang.Class对象，来代表的这个类，作为方法区这些数据的入口�? <strong>链接</strong></p></li><li><p>验证：保证二进制的字节流所包含的信息符号虚拟机的要求，并且不会危害到虚拟机自身的安全�?2. 准备：为 static 静态变量（类变量）分配内存，并为其设置初始值�? - 注：这些内存都将在方法区内分配内存，实例变量在堆内存中，而且实例变量是在对象初始化时才赋�?3. 解析：解析阶段就是虚拟机将常量池中的符号引用转化为直接引用的过程�? - 例如 import xxx.xxx.xxx 属于符号引用，而通过指针或者对象地址引用就是直接引用</p></li></ol><p>*<em>初始�?</em></p><ol><li>初始化会对变量进行赋值，即对最初的零值，进行显式初始化，例如<code>static int num = 0</code>变成了<code>static int num = 3</code>，这些工作都会在类构造器<code>&lt;clinit&gt;()</code>方法中执行。而且虚拟机保证了会先去执行父类<code>&lt;clinit&gt;()</code>方法 �? - 如果在静态代码块中修改了静态变量的值，会对前面的显示初始化的值进行覆�? <strong>卸载</strong></li></ol><p>GC 垃圾回收内存中的无用对象</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/404.png" alt="image-20211129160821148" style="zoom:80%;"><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/404.png" alt="image-20211129160821148" style="zoom:80%;"><h2 id="api是干什么用�" tabindex="-1"><a class="header-anchor" href="#api是干什么用�"><span>api是干什么用�?</span></a></h2><p>相当于接口，我们只需要怎么使用参数和返回值，就能得到对应的结�?</p><h2 id="servlet的工作原�" tabindex="-1"><a class="header-anchor" href="#servlet的工作原�"><span>servlet的工作原�?</span></a></h2><p>在Java Web程序中，<strong>Servlet</strong>主要负责接收用户请求 <code>HttpServletRequest</code>,在<code>doGet()</code>,<code>doPost()</code>中做相应的处理，并将回应<code>HttpServletResponse</code>反馈给用户�? <em><em>生命周期�?</em> <strong>Web容器加载Servlet并将其实例化后，Servlet生命周期开�?*，容器运行其</strong>init()方法</em><em>进行Servlet的初始化；请求到达时调用Servlet�?*service()方法</em><em>，service()方法会根据需要调用与请求对应�?*doGet或doPost</em><em>等方法；当服务器关闭或项目被卸载时服务器会将Servlet实例销毁，此时会调用Servlet�?*destroy()方法</em><em>�?*init方法和destroy方法只会执行一次，service方法客户端每次请求Servlet都会执行</em>*�? <a href="https://www.cnblogs.com/logsharing/p/8448446.html" target="_blank" rel="noopener noreferrer">GET和POST两种基本请求方法的区�?- 在途中# - 博客�?(cnblogs.com)</a></p><h2 id="数据库索引有哪些-使用它们的优点和缺�" tabindex="-1"><a class="header-anchor" href="#数据库索引有哪些-使用它们的优点和缺�"><span>数据库索引有哪些？使用它们的优点和缺�?</span></a></h2><p>索引的优点： �?建立索引的列可以保证行的唯一性，生成唯一的rowId</p><p>�?建立索引可以有效缩短数据的检索时�? �?建立索引可以加快表与表之间的连接</p><p>�?为用来排序或者是分组的字段添加索引可以加快分组和排序顺序</p><p>索引的缺点： �?创建索引和维护索引需要时间成本，这个成本随着数据量的增加而加�? �?创建索引和维护索引需要空间成本，每一条索引都要占据数据库的物理存储空间，数据量越大，占用空间也越大（数据表占据的是数据库的数据空间）</p><p>�?会降低表的增删改的效率，因为每次增删改索引需要进行动态维护，导致时间变长</p><p>什么情况下需要建立索�? 数据量大的，经常进行查询操作的表要建立索引�? 用于排序的字段可以添加索引，用于分组的字段应当视情况看是否需要添加索引�? 表与表连接用于多表联合查询的约束条件的字段应当建立索引�?</p><h2 id="try-catch和throws的区别-遇到异常try-catch和不try-catch的区别-finally语句是不是一定会执行-它里面会放什么样的语句" tabindex="-1"><a class="header-anchor" href="#try-catch和throws的区别-遇到异常try-catch和不try-catch的区别-finally语句是不是一定会执行-它里面会放什么样的语句"><span>try-catch和throws的区别，遇到异常try-catch和不try-catch的区别？finally语句是不是一定会执行？它里面会放什么样的语句？</span></a></h2><p>try-catch 自己处理异常</p><p>throws 用再方法上，抛出异常给上�? 如果遇到检查异常（属于exception），会让你处理使用throw throws try-catch处理；其他的会默认交给jvm处理</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/note/202111282034041.png" alt="image-20211127171400401" style="zoom:80%;">`,60)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};